STANDARD = 'Which choice completes the text so that it conforms to the conventions of Standard English?'
STEMS = {
'central-ideas': 'Which choice best states the main idea of the text?',
'quantitative-evidence': 'Which choice best uses data from the table to support the claim?',
'inferences': 'Which choice most logically completes the text?',
'transitions': 'Which choice completes the text with the most logical transition?',
'boundaries': STANDARD, 'form-structure': STANDARD,
}


def c(passage, right, wrong, evidence, steps, topic, stem=None, table=None, difficulty='hard'):
    return dict(passage=passage, right=right, wrong=wrong, evidence=evidence,
                steps=steps, topic=topic, stem=stem, table=table, difficulty=difficulty)


